-- Reconcile the stored, unused v3 onboarding city choices with the live advertising board.
-- Old regional choices remain available; the new individual cities are appended.
-- This only changes the stored form and printer, never ClickUp or client records.
BEGIN;
SET LOCAL lock_timeout = '1s';
SET LOCAL statement_timeout = '30s';
LOCK TABLE public.cockpit_forms IN ACCESS EXCLUSIVE MODE NOWAIT;
LOCK TABLE public.cockpit_form_versions IN SHARE ROW EXCLUSIVE MODE NOWAIT;
LOCK TABLE public.cockpit_form_invites, public.cockpit_form_responses IN SHARE ROW EXCLUSIVE MODE NOWAIT;
DO $$
DECLARE v_schema_hash text; v_map_hash text; v_stage jsonb; v_switch jsonb; v_form public.cockpit_forms%ROWTYPE;
BEGIN
  SELECT * INTO v_form FROM public.cockpit_forms WHERE key='onboarding' FOR UPDATE NOWAIT;
  IF NOT FOUND OR v_form.provider IS DISTINCT FROM 'typeform' OR v_form.version IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'Onboarding registry changed; stop and re-read it.' USING ERRCODE='55000';
  END IF;
  SELECT value INTO v_stage FROM public.cockpit_settings WHERE key='forms.stage4' FOR UPDATE NOWAIT;
  SELECT value INTO v_switch FROM public.cockpit_settings WHERE key='forms.client.schema_v2' FOR UPDATE NOWAIT;
  IF v_stage->'onboarding' IS DISTINCT FROM 'false'::jsonb OR v_switch->>'state' IS DISTINCT FROM 'off' THEN
    RAISE EXCEPTION 'Onboarding or its structured switch is not off; stop and re-read it.' USING ERRCODE='55000';
  END IF;
  SELECT md5(schema::text) INTO v_schema_hash FROM public.cockpit_form_versions WHERE form_key='onboarding' AND version=3 FOR UPDATE NOWAIT;
  SELECT md5(regexp_replace(prosrc, '\s+', ' ', 'g')) INTO v_map_hash FROM pg_catalog.pg_proc
    WHERE oid=to_regprocedure('public.cockpit_form_stage4_print_map(integer)');
  IF NOT coalesce((v_schema_hash, v_map_hash) IN (('2e187490c06d61169588bc9724870aed','b191254e98dd061f2d002d825fc25962'), ('ca5a873dd26eeb55299c5f6da4a1bba0','186e2eba8faee3d5d893ad021a35b33e')), false) THEN
    RAISE EXCEPTION 'The version-3 schema or printer changed; stop and re-read it.' USING ERRCODE='55000';
  END IF;
  IF v_schema_hash='2e187490c06d61169588bc9724870aed' AND (EXISTS (SELECT 1 FROM public.cockpit_form_invites WHERE form_key='onboarding' AND form_version=3)
      OR EXISTS (SELECT 1 FROM public.cockpit_form_responses WHERE form_key='onboarding' AND form_version=3)) THEN
    RAISE EXCEPTION 'Version 3 has been used; preserve it and use a new form version.' USING ERRCODE='55000';
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.cockpit_form_stage4_print_map(p_version integer)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF p_version = 3 THEN
    RETURN '{"version":3,"refs":[{"ref":"533f14a0-712f-4de9-9ac7-67e1be6bc0c8","title":"Full Name","print":{"text":"fullName"}},{"ref":"64f2fb80-b074-4017-b8b7-b7d549947e52","title":"Phone","print":{"text":"phone"}},{"ref":"7994f0d2-baeb-451b-983a-816290873a68","title":"Email","print":{"text":"email"}},{"ref":"514bfd3f-4ca1-469e-b9e7-87656503f65c","title":"Business Name","print":{"text":"businessName"}},{"ref":"e5caee43-e9b5-427d-8583-6982c5dd9be8","title":"Please enter your business address.","print":{"text":"address"}},{"ref":"f7f9f2eb-1761-4c28-83ed-a53621c2cf88","title":"Paste a Google Maps link to your location (optional).","print":{"text":"mapsLink"}},{"ref":"454a425f-2ac6-4d94-92db-cec08618600e","title":"Website URL","print":{"tickText":"noWebsite","whenTicked":"No website yet","else":{"text":"website"}}},{"ref":"adecfe45-5d55-4319-98ff-3761e04bfc9b","title":"Instagram URL","print":{"text":"instagram"}},{"ref":"575d17ed-e26d-4e55-87d3-7cb31cb71939","title":"Facebook Page URL","print":{"tickText":"noFacebookPage","whenTicked":"No Facebook page","else":{"text":"facebook"}}},{"ref":"ee25f923-d5e1-4d1a-a95f-cd9c17abbe83","title":"What payment options do you currently offer to your clients (e.g., full payment, installment plans, minimum down payment, in-house financing, third-party financing)?","print":{"lines":[{"list":"paymentMethods","labels":{"full":"Full payment","instalments":"Installment plans","down_payment":"Down payment first","in_house":"In-house financing","third_party":"Third-party financing"}},{"text":"paymentDetails"}]}},{"ref":"282dac48-5031-4acb-96b6-ea469e8a5a8b","title":"Front Desk Phone","print":{"text":"frontDeskPhone"}},{"ref":"09d2e62a-51d4-4665-a3a9-30f5279b71bc","title":"Personal Phone Number","print":{"text":"personalPhone"}},{"ref":"ed1ba2fe-2827-4eea-a678-62205f1ce9f5","title":"How long have you been in business?","print":{"number":"startYear","template":"Since {n}"}},{"ref":"7a120dbb-0169-4bcc-9193-5c525a470d02","title":"Current booking software","print":{"list":"bookingTools","labels":{"whatsapp":"WhatsApp","phone":"Phone calls","paper_excel":"Notebook or Excel","google_calendar":"Google Calendar","calendly":"Calendly","other_software":{"text":"bookingOther"}}}},{"ref":"ddf2767d-5725-4df2-b200-f0aab77a2db5","title":"Do you have a facebook business manager or have you ever ran ads on meta (Facebook & Instagram) in the past?","print":{"choice":"facebookAds","labels":{"yes":"Yes","unsure":"IM UNSURE | لست متأكدًا","ran_before":"I''ve ran ads before but dont know how to access my Account |شغّلت إعلانات من قبل لكنني لا أعرف كيف أصل إلى حسابي","never_ran":"I Have a Business Account but have never ran ads | لديّ حساب أعمال على فيسبوك لكنني لم أقم بتشغيل إعلانات من قبل","restricted":"My Account is restricted | حسابي مقيّد"}}},{"ref":"0a6b5704-c46d-480c-a592-b59108683596","title":"How many projects has your company completed to date?","print":{"number":"projectsDone","template":"{n}"}},{"ref":"b7873d40-d154-42ac-bf24-cb3b667e84cc","title":"Business hours - When are you open to schedule?","print":{"join":": ","parts":[{"list":"hoursDays","labels":{"sun":"Sun","mon":"Mon","tue":"Tue","wed":"Wed","thu":"Thu","fri":"Fri","sat":"Sat"}},{"text":"hoursTimes"}]}},{"ref":"d976036f-6c2e-4d5d-999a-64cf9bb2ef02","title":"1) What services do you offer list all of them? Also I want to know which ones have the HIGHEST price point and Highest Profit 2) What is the PRICE of the services?","print":{"rows":"services","line":"{name}{price? : {unit=starts_from?starting from }{price} {CUR}{unit!=starts_from? {unit}}}{topPrice? (highest price)}{topProfit? (most profit)}","units":{"project":"per project","sqm":"per square metre","visit":"per visit","starts_from":""}}},{"ref":"6271b610-6946-4056-bb08-d03ffc274141","title":"Out of those what is the #1 service/type of project you want to focus on scaling?","print":{"text":"serviceFocus"}},{"ref":"f2b7bc2b-2a79-4640-9e21-377e7aa39d45","title":"What are your top five most frequently asked questions and their answers? (Feel free to add more — the more detailed, the better.)","print":{"rows":"faqs","line":"{n}. {question}\n{answer}","sep":"\n\n"}},{"ref":"6c819933-3eb9-4db8-bd59-d39be11cb7f0","title":"Please describe your ideal project in detail.","print":{"text":"idealProject"}},{"ref":"fa017616-3fb5-4e64-9fbd-39cea6e26c47","title":"What service areas do you cover? Please list all cities and neighborhoods you serve so we can target your ads precisely.","print":{"areas":"areaCountries","countries":{"sa":"Saudi Arabia","kw":"Kuwait","ae":"UAE","qa":"Qatar","bh":"Bahrain","om":"Oman"},"lists":{"sa":"areasSA","kw":"areasKW","ae":"areasAE","qa":"areasQA","bh":"areasBH","om":"areasOM"},"other":"areasOther","note":"areasNote","labels":{"sa":{"all_sa":"All of Saudi Arabia","riyadh":"Riyadh","jeddah":"Jeddah","makkah":"Makkah","madinah":"Madinah","dammam":"Dammam","khobar":"Khobar","dhahran":"Dhahran","qatif":"Qatif","ahsa":"Al Ahsa","jubail":"Jubail","qassim":"Qassim","taif":"Taif","abha_khamis":"Abha and Khamis Mushait","tabuk":"Tabuk","hail":"Hail","jazan":"Jazan","najran":"Najran","yanbu":"Yanbu","abha":"Abha","buraydah":"Buraydah","khamis_mushait":"Khamis Mushait","unaizah":"Unaizah","al_kharj":"Al Kharj","hofuf":"Hofuf","sakaka":"Sakaka","arar":"Arar","al_bahah":"Al Bahah"},"kw":{"all_kw":"All of Kuwait","capital":"Capital","hawalli":"Hawalli","farwaniya":"Farwaniya","mubarak":"Mubarak Al-Kabeer","ahmadi":"Ahmadi","jahra":"Jahra","kuwait_city":"Kuwait City","salmiya":"Salmiya","sabah_al_salem":"Sabah Al Salem"},"ae":{"all_ae":"All of the UAE","dubai":"Dubai","abu_dhabi":"Abu Dhabi","sharjah":"Sharjah","ajman":"Ajman","al_ain":"Al Ain","rak":"Ras Al Khaimah","fujairah":"Fujairah","uaq":"Umm Al Quwain","khor_fakkan":"Khor Fakkan","kalba":"Kalba","dibba":"Dibba"},"qa":{"all_qa":"All of Qatar","doha":"Doha","rayyan":"Al Rayyan","lusail":"Lusail","wakrah":"Al Wakrah","khor":"Al Khor","umm_salal":"Umm Salal","daayen":"Al Daayen","dukhan":"Dukhan"},"bh":{"all_bh":"All of Bahrain","capital":"Capital (Manama)","muharraq":"Muharraq","northern":"Northern","southern":"Southern","manama":"Manama","ar_rifa":"Ar Rifa","hamad_town":"Hamad Town","isa_town":"Isa Town","sitra":"Sitra","budaiya":"Budaiya","jidd_hafs":"Jidd Hafs"},"om":{"all_om":"All of Oman","muscat":"Muscat","dhofar":"Dhofar (Salalah)","batinah":"Al Batinah (Sohar)","dakhiliyah":"Ad Dakhiliyah (Nizwa)","sharqiyah":"Ash Sharqiyah","salalah":"Salalah","sohar":"Sohar","nizwa":"Nizwa","sur":"Sur","barka":"Barka","rustaq":"Rustaq","al_sib":"Al-Sib","buraimi":"Buraimi"}}}},{"ref":"b370341c-6ea3-43c9-bd8c-16e278a2d2d5","title":"What types of appointments do you offer? (Select all that apply)","print":{"list":"appointmentTypes","labels":{"online":"عن بُعد (أونلاين) | Online","onsite":"في موقع العميل / في المنزل | Onsite / In-home","office":"في مقرّكم / مكتبكم | In your office"},"sep":", ","order":"ticked"}},{"ref":"35ea63c3-090a-425d-b75c-e3d183d48cd1","title":"What''s the maximum distance you would travel from your office to do an in-home consultation?","print":{"choice":"distanceMode","labels":{"anywhere":"Anywhere in our service areas","limit":{"number":"maxDistanceKm","template":"{n} km"}}}},{"ref":"b7c403ea-8d66-4814-80cf-7e8d7fdb8d11","title":"Local Landmark Information (Please type this in the format shown) - Located next to the Burger King down King Saud street on the left hand side.","print":{"text":"landmark"}},{"ref":"a20cfc1a-0228-413d-80ab-d97fc97574e0","title":"Appointment length + details + buffer","print":{"lines":[{"template":"{apptMinutes} minutes, {bufferMinutes=0?no time:{bufferMinutes} minutes} between appointments"},{"text":"apptDetails"}]}},{"ref":"0a80a0a8-3a09-4907-a1d1-6c57e57d4c47","title":"Who are the engineers in your business that will be giving these consultations?","print":{"rows":"consultants","line":"{name} - {speciality}{nationality? - {nationality}}{qualifications? - {qualifications}}"}},{"ref":"7426c6c5-344f-44c9-9999-3b9daf3a06b8","title":"What motivated you to join our program? What was the reason you signed up?","print":{"text":"whyJoined"}},{"ref":"ec89854f-d006-402b-958a-91738e2b3e7a","title":"Do you offer free consultations?","print":{"choice":"freeConsults","labels":{"yes":"Yes, we do offer free consultations / نعم، نقدم استشارات مجانية✅","open_to_it":"No, but we''re open to considering it / حاليا لا نقدمها، لكن يمكننا مناقشه🤝","no":"No, we do not offer free consultations / لا، لا نقدم استشارات مجانية❌"}}},{"ref":"bf8c7c7b-fff9-463f-b30a-8d8ca8b622f6","title":"What is your marketing process? In other words... please explain EVERYTHING A-Z that you have in place or have tried to generate new projects","print":{"lines":[{"list":"marketingChannels","prefix":"Channels: ","labels":{"referrals":"Referrals","instagram":"Instagram","meta_ads":"Facebook and Instagram ads","google":"Google","tiktok":"TikTok","snapchat":"Snapchat","website":"Website","exhibitions":"Exhibitions and events","whatsapp":"WhatsApp","agency":"A marketing agency","none_yet":"Nothing yet"}},{"text":"marketing"}]}},{"ref":"7ff5d37a-df7f-4002-8248-d0b4af6c28e8","title":"Last Calendar Year - How Much Total Revenue did you do?","print":{"number":"lastRevenue","template":"{n}","make":"number"}},{"ref":"fcf43e6a-cc84-4ae7-9cef-2336069d0280","title":"What are the TOP 3 challenges that - if we were able to help you with - would make you 100% satisfied with your investment? - Be specific.","print":{"text":"challenges"}},{"ref":"791b99b8-c7e9-40a4-96d6-868399e1ae97","title":"What is your realistic goal revenue in 90 Days?","print":{"number":"goal90","template":"{n}","make":"number"}},{"ref":"f4b96a9b-bd7c-4398-98b4-6a28a7d3595a","title":"What is your ideal/stretch revenue goal within the next 12-24 months?","print":{"number":"goal12","template":"{n}","make":"number"}},{"ref":"41d2d5bb-b023-4fa4-906c-72aeef7a5e46","title":"Any additional information we should know before starting?","print":{"text":"additionalInfo"}},{"ref":"64d23c81-1784-4f07-8356-107af764fc95","title":"Please attach a Google Drive link to all the content you have for your office (See check list below)","print":{"text":"driveLink"}}],"sidecar":{"keysExcluded":["fullName","phone","email","frontDeskPhone","personalPhone"]}}'::jsonb;
  END IF;
  RETURN NULL;
END $$;

DO $$
DECLARE
  v_old jsonb; v_new jsonb; v_fields jsonb; v_problem text;
  v_add jsonb := '{"areasSA":[{"value":"abha","label":{"en":"Abha","ar":"أبها"}},{"value":"buraydah","label":{"en":"Buraydah","ar":"بريدة"}},{"value":"khamis_mushait","label":{"en":"Khamis Mushait","ar":"خميس مشيط"}},{"value":"unaizah","label":{"en":"Unaizah","ar":"عنيزة"}},{"value":"al_kharj","label":{"en":"Al Kharj","ar":"الخرج"}},{"value":"hofuf","label":{"en":"Hofuf","ar":"الهفوف"}},{"value":"sakaka","label":{"en":"Sakaka","ar":"سكاكا"}},{"value":"arar","label":{"en":"Arar","ar":"عرعر"}},{"value":"al_bahah","label":{"en":"Al Bahah","ar":"الباحة"}}],"areasKW":[{"value":"kuwait_city","label":{"en":"Kuwait City","ar":"مدينة الكويت"}},{"value":"salmiya","label":{"en":"Salmiya","ar":"السالمية"}},{"value":"sabah_al_salem","label":{"en":"Sabah Al Salem","ar":"صباح السالم"}}],"areasAE":[{"value":"khor_fakkan","label":{"en":"Khor Fakkan","ar":"خورفكان"}},{"value":"kalba","label":{"en":"Kalba","ar":"كلباء"}},{"value":"dibba","label":{"en":"Dibba","ar":"دبا"}}],"areasQA":[{"value":"dukhan","label":{"en":"Dukhan","ar":"دخان"}}],"areasBH":[{"value":"manama","label":{"en":"Manama","ar":"المنامة"}},{"value":"ar_rifa","label":{"en":"Ar Rifa","ar":"الرفاع"}},{"value":"hamad_town","label":{"en":"Hamad Town","ar":"مدينة حمد"}},{"value":"isa_town","label":{"en":"Isa Town","ar":"مدينة عيسى"}},{"value":"sitra","label":{"en":"Sitra","ar":"سترة"}},{"value":"budaiya","label":{"en":"Budaiya","ar":"البديع"}},{"value":"jidd_hafs","label":{"en":"Jidd Hafs","ar":"جد حفص"}}],"areasOM":[{"value":"salalah","label":{"en":"Salalah","ar":"صلالة"}},{"value":"sohar","label":{"en":"Sohar","ar":"صحار"}},{"value":"nizwa","label":{"en":"Nizwa","ar":"نزوى"}},{"value":"sur","label":{"en":"Sur","ar":"صور"}},{"value":"barka","label":{"en":"Barka","ar":"بركاء"}},{"value":"rustaq","label":{"en":"Rustaq","ar":"الرستاق"}},{"value":"al_sib","label":{"en":"Al-Sib","ar":"السيب"}},{"value":"buraimi","label":{"en":"Buraimi","ar":"البريمي"}}]}'::jsonb;
BEGIN
  SELECT schema INTO v_old FROM public.cockpit_form_versions WHERE form_key='onboarding' AND version=3;
  IF md5(v_old::text)='ca5a873dd26eeb55299c5f6da4a1bba0' THEN RETURN; END IF;
  SELECT jsonb_agg(CASE WHEN v_add ? (f->>'key')
      THEN jsonb_set(jsonb_set(f,'{options}',(f->'options') || (v_add->(f->>'key'))),'{hint}', '{"en":"If you select the whole country, you do not need to select individual cities.","ar":"إذا اخترتوا الدولة كلها، ما يحتاج تختارون كل مدينة بروحها."}'::jsonb) ELSE f END ORDER BY n) INTO v_fields
    FROM jsonb_array_elements(v_old->'fields') WITH ORDINALITY AS x(f,n);
  v_new := jsonb_set(v_old,'{fields}',v_fields);
  IF md5(v_new::text) IS DISTINCT FROM 'ca5a873dd26eeb55299c5f6da4a1bba0' THEN
    RAISE EXCEPTION 'Updated version-3 schema differs from the reviewed copy: %', md5(v_new::text) USING ERRCODE='55000';
  END IF;
  v_problem := coalesce(public.cockpit_form_schema_check(v_new), public.cockpit_form_schema_text_problem(v_new),
                        public.cockpit_form_stage4_print_problem(3,v_new));
  IF v_problem IS NOT NULL THEN RAISE EXCEPTION 'Updated version-3 schema failed validation: %',v_problem USING ERRCODE='22023'; END IF;
  PERFORM set_config('cockpit.audit_actor','migration 20261105102219',true);
  PERFORM set_config('cockpit.audit_source','migration',true);
  PERFORM set_config('cockpit.forms_action','forms.onboarding_v3_areas',true);
  UPDATE public.cockpit_form_versions SET schema=v_new WHERE form_key='onboarding' AND version=3 AND md5(schema::text)='2e187490c06d61169588bc9724870aed';
  IF NOT FOUND THEN RAISE EXCEPTION 'Version 3 changed; stop and re-read it.' USING ERRCODE='55000'; END IF;
  PERFORM set_config('cockpit.forms_action','',true);
END $$;
COMMIT;
